use lg_core::{currency, Money, RoundingMode};
use lg_fmt::{format_amount, Locale};

#[test]
fn disc_l02() {
    let jpy = currency::require("JPY").unwrap();
    let m = Money::parse("1234", jpy, RoundingMode::HalfEven).unwrap();
    assert_eq!(m.minor(), 1234);
    assert_eq!(format_amount(m, &Locale::by_tag("en-US").unwrap()), "¥1,234");
}
